import { createHmac, timingSafeEqual } from "node:crypto";
function verifyFrankWebhook(rawBody, header, signingSecret) {
  // rawBody must contain the original HTTP request body bytes.
  if (!Buffer.isBuffer(rawBody)) {
    throw new Error("Expected raw request body Buffer");
  }
  if (
    typeof header !== "string" ||
    !/^v1=[0-9a-f]{64}$/.test(header)
  ) {
    return false;
  }
  const expected = createHmac("sha256", signingSecret)
    .update(rawBody)
    .digest();
  const received = Buffer.from(header.slice(3), "hex");
  return timingSafeEqual(expected, received);
}

